from pathlib import Path
import json
r=Path(__file__).resolve().parents[3];a=Path(__file__).parent;ed=json.loads((a/'edits.json').read_text())
def rep(path,old,new,ids):
 p=r/path;s=p.read_text();assert s.count(old)==1,(path,old[:60],s.count(old));p.write_text(s.replace(old,new));ed.append({'file':path,'ids':ids,'before':old,'after':new})
def add_before(path,anchor,new,ids):rep(path,anchor,new+'\n\n'+anchor,ids)
p='thesis/body/ch01_introduction.tex'
add_before(p,'触觉模拟因传感机制不同而呈现不同路线。',r'物理引擎与操作研究框架承担不同职责。MuJoCo提供关节、执行器、固定腱以及接触约束等计算机制，具体机器人的任务状态机、触觉布局与数据记录仍需在其上组织。SAPIEN将PhysX、关节物体资产与渲染接口结合，侧重可交互物体及部件级操作\cite{xiang2020sapien}；其任务与资产组织方式为操作研究提供了另一种平台基础。本文选择MuJoCo描述欠驱动传动与接触，并自行组合模型、控制、任务和记录接口，使触觉读出能够随操作过程保存。这一选择依据当前机构和数据接口需求，不以引擎名称推断其他平台的欠驱动建模能力。',[23])
add_before(p,'数据集研究从采集来源、环境覆盖和模态组成等方面扩展了操作学习的条件。',r'仿真框架进一步将物理计算组织为可复用的操作环境。robosuite在MuJoCo上组合机器人、控制器、场景和观测接口，支持按任务配置环境并复用控制频率、奖励和回合设置\cite{zhu2020robosuite}。ManiSkill则基于SAPIEN提供多样关节物体与操作任务，并组织点云、RGB-D及专家示教以支持交互学习和示教学习\cite{mu2021maniskill}。前者强调模块化机器人环境，后者强调物体变化与技能泛化，两者都说明规模化数据采集需要同时设计任务接口、控制和记录流程。本文据此将特定欠驱动手与曲面触觉读出纳入统一环境，并单独检查示教记录的语义与时序。',[22])
add_before(p,'操作示教可以通过人工遥操作获得，也可以依托规划、控制器和已有轨迹自动生成。',r'灵巧手人工示教同时涉及手臂定位、多指姿态与接触保持。本文前期在仿真中尝试交互式示教时，观察到手指遮挡使局部接触难以从单一视角判断，多指协调和手臂运动又增加了反复调整成本。这是作者的定性操作经验。相关研究将感知、运动重定向与避碰作为遥操作系统的共同问题：AnyTeleop通过模块化手姿估计、重定向和运动生成适配不同手臂与手型，并报告快速运动跟踪丢失和手部自遮挡造成的姿态不可靠问题\cite{qin2023anyteleop}。因此，仿真中的人工示教同样需要合适的交互与反馈接口，自动构建可执行轨迹可以补充单纯依靠人工重复操作的采集方式。',[24])
rep(p,'本文面向途见科技灵巧手的712维处理后触觉，仿真端采用MuJoCo原生触觉读出，真实端使用既有实机记录，监督对应的构造条件与该研究不同。','本文同样分别学习两域表示并研究潜变量映射，但观测和监督来源有所不同：目标为途见科技灵巧手的712维处理后标量响应，仿真读出来自MuJoCo原生touch及处理链，真实侧来自既有实机记录；监督由真实统计先验引导物理探针构造。本文因而既研究统计伪配对如何建立，也检验由此获得的映射向自然任务仿真输入推广时的适用性，最终评价完整触觉窗口的分布与结构。',[25])
